import os,re,subprocess,collections
patterns=[(re.compile(rb'\b(?:AKIA|ASIA)[A-Z0-9]{16}\b'),b'<your-aws-access-key-id>'),(re.compile(rb'\bgh[pousr]_[A-Za-z0-9]{20,}\b|\bgithub_pat_[A-Za-z0-9_]{20,}\b'),b'<your-github-token>'),(re.compile(rb'\bhf_[A-Za-z0-9]{20,}\b'),b'<your-huggingface-token>')]
files={}
for root,dirs,names in os.walk('.'):
 dirs[:]=[d for d in dirs if d!='.git']
 for name in names:
  p=os.path.join(root,name)
  if not os.path.islink(p):files[p]=open(p,'rb').read()
secrets={}
for data in files.values():
 for pat,placeholder in patterns:
  for m in pat.finditer(data):secrets[m[0]]=placeholder
 pat=re.compile(rb'''AWS_SECRET_ACCESS_KEY["']?\s*(?:=|\]\s*=)\s*["']?([A-Za-z0-9/+=]{40})(?![A-Za-z0-9/+=])''',re.I)
 for m in pat.finditer(data):secrets[m[1]]=b'<your-aws-secret-access-key>'
counts=collections.Counter();changed=[]
for path,data in files.items():
 new=data
 for secret,placeholder in secrets.items():
  counts[placeholder.decode()]+=new.count(secret)
  new=new.replace(secret,placeholder)
 if new!=data:
  with open(path,'wb') as f:f.write(new)
  changed.append(path)
for path in changed:print('Sanitized:',path)
print('Replacement counts:',dict(counts))
assert all(not any(s in open(p,'rb').read() for s in secrets) for p in files)
print('Verified: original secret values absent from all working-tree files (%d files).'%len(files))
objects=subprocess.check_output(['git','rev-list','--objects','--all']).splitlines()
hits=0
for entry in objects:
 oid=entry.split(b' ',1)[0]
 if subprocess.check_output(['git','cat-file','-t',oid]).strip()==b'blob':
  data=subprocess.check_output(['git','cat-file','blob',oid])
  if any(s in data for s in secrets):hits+=1
print('Git history blobs containing original secrets:',hits)
